namespace docking.widgets.filter;



using ghidra.util;

/**
 * A filter that will pass text when it matches exactly.
 */
public class MatchesExactlyTextFilter : MatchesPatternTextFilter {

	public MatchesExactlyTextFilter(string filterText, bool caseSensitive,
			bool allowGlobbing) : base(filterText, caseSensitive, allowGlobbing)
    {
	}

	/* @Override */
	protected Pattern createPattern() {
		int options = Pattern.DOTALL;
		if (!caseSensitive) {
			options |= Pattern.CASE_INSENSITIVE;
		}

		Pattern pattern = UserSearchUtils.createPattern(filterText, allowGlobbing, options);
		return pattern;
	}

	/* @Override */
	public bool isSubFilterOf(TextFilter filter) {
		// we matched exactly--there can be no further sub-filter
		return false;
	}

}
